#!/usr/bin/env python3
"""Writes outputs/g1_grasp/protocol_freeze.json BEFORE any G1 outcome exists (refuses to overwrite).  Run: python3 eval/g1_freeze.py"""
import json, sys, time, hashlib
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent; sys.path.insert(0, str(ROOT / "eval")); D = ROOT / "outputs/g1_grasp"; F = D / "protocol_freeze.json"
if F.exists(): sys.exit("freeze exists")
if (D / "results").exists() and any((D / "results").glob("g1_results.json")): sys.exit("results exist before freeze")
sh = lambda p: hashlib.sha256((ROOT / p).read_bytes()).hexdigest()
import closed_loop_pilot as P, g1_grasp as G
rep = json.loads((D / "integration_report.json").read_text()); assert rep["verdict"] == "PASS" and rep["n_gates"] == 11
for f, h in rep["code_sha256"].items(): assert sh(f) == h, f
poses, mind = G.sample_poses(); files = ["eval/g1_grasp.py", "eval/test_g1_grasp.py", "eval/g1_analysis.py", "eval/g1_freeze.py", "eval/branching_replay.py", "eval/branching_metrics.py", "eval/closed_loop_pilot.py", "eval/indep_manifest.py" if (ROOT / "data/indep_manifest.py").exists() is False else "data/indep_manifest.py", "policies/baseline.py", "sim/ik.py", "sim/lab_env.py", "sim/lab_scene.py", "control/safety_limits.py", "control/action_adapter.py", "eval/metrics.py", "outputs/indep/manifest.json"]
design = {s: [dict(id=c["id"], levels=c["levels"], th=c["th"]) for c in G.design(s)] for s in G.STATES}
fz = dict(name="G1 physically parameterised grasp candidates - protocol freeze", frozen_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), g1_outcomes_exist_at_freeze=False, label="DEVELOPMENT; ORACLE-POSE candidate generation (IK uses the simulator box pose); simulation only; no model, no training; the 24 poses are development-only after G1",
          poses=poses, poses_sha256=hashlib.sha256(json.dumps(poses, sort_keys=True).encode()).hexdigest(), pose_rng=[20261102, 9001], min_chebyshev_to_any_previously_used_state=mind, pose_selection="drawn without looking at any model, candidate or outcome; 12 hard (x 0.34-0.38) + 12 mid (x 0.38-0.47); y 0.07-0.13; yaw -0.20..0.20; no reserved seeds 31-33; none of these poses selected the candidate ranges",
          decision_states={s: f"first step of nominal segment '{G.DECISION_SEG[s]}'" for s in G.STATES}, factors=G.FACTORS, levels=G.LEVELS, nominal=G.NOMINAL, design=design, design_note="c0 = nominal scripted grasp = the DEFAULT; c1..c8 = 2-level fractional factorial (D=ABC for 4 factors at D1/D2; full 2^3 at D3) in fixed order",
          level_rationale="geometry/actuator anchored before any G1 outcome: depth +-1 cm (box 4 cm cube, half-width 2 cm); lateral +-5 mm; yaw +-0.05 rad; pre-grasp distance 0.09 +-0.02 m; closing aperture command 0.012 +-0.004 m (finger ctrlrange -0.005..0.044 m); close dwell +2/+8 control steps; closing duration 0.4/1.0 s (nominal 0.7 s)",
          execution=dict(semantics="16-D absolute actuator targets from IK (+gravity compensation), clip->slew (2.0 rad/s arm, 0.2 m/s gripper at 20 Hz) from the last executed command; snapshot = mj_copyData + prev_ctrl + time", horizon="each candidate is executed to the end of its own plan = end of 'lift_hold' (8 control steps = 0.4 s at the lift height); nominal plan length 85 steps; no extension"),
          outcome=dict(GRASP_SUCCESS="closure complete (>=2 finger-box contacts at the start of lift) AND for all 9 rows of the hold window [start of lift_hold .. final row]: box rise >= 0.05 m above its initial height AND |box - TCP| < 0.06 m; AND slip (max deviation of box-TCP vector from its hold-window mean) <= 0.01 m; AND no drop (rise never < 0.02 m after first reaching 0.05 m)",
                       reasons="success | not_closed | dropped | not_lifted | slipped (precedence in that order)", PALM_EVENT="hand force > 0.01 N at any row from the decision state to the end", PALM_FREE_SUCCESS="GRASP_SUCCESS and no PALM_EVENT (secondary)", VALID="IK ok (pos err<2 mm, rot err<0.03, 0 failed steps) AND prefix equal to the nominal prefix AND executed chain legal and finite AND no robot-obstacle (desk/tray/room) contact",
                       NOT_EVALUABLE="invalid candidates; states whose default (c0) is invalid", distinct="candidate is distinct from nominal if executed arm L-inf >= 0.02 rad OR gripper L-inf >= 0.002 m OR TCP max deviation >= 0.003 m"),
          headroom=dict(definition="state has meaningful oracle headroom iff the default (c0) GRASP_SUCCESS = 0 and >= 1 valid candidate GRASP_SUCCESS = 1 (binary gap 1 >= 0.5); secondary quality headroom = max slip reduction among states where both succeed", comparisons="default (c0), uniform random (expected over valid candidates), simplest physical heuristic (D1/D2: first candidate with depth level -1 = c1; D3: first candidate with closing-duration level +1 = c3; falls back to default if invalid), oracle best-of-9; pose-cluster bootstrap 10000, seed 0, 95 %"),
          stop_rules=["valid candidate fraction < 80 % -> STOP", "> 80 % of decision states without meaningful oracle headroom -> STOP this candidate family", "non-deterministic snapshot / controller restoration or action/IK/collision semantics failure -> STOP (integration gates)", "CPU cap 0.25 process CPU-h for all of G1 -> PARTIAL, no retry, no extension"], compute=dict(cap_total_s=G.CAP_TOTAL_S, ledger_used_at_freeze_s=G.ledger_used()),
          files_sha256={f: sh(f) for f in files})
P.atomic_json(F, fz); print(hashlib.sha256(F.read_bytes()).hexdigest(), fz["frozen_at"], len(files), "files; ledger", fz["compute"]["ledger_used_at_freeze_s"], "poses", len(poses), "min dist", mind)
